//! Stream u4's site rows (the run-time texture helper, `runtime/ui/texture.rs`): generated by `tools/gen_sites_u4.py` from the
//! owned 13.0.5 `main` (the guard bytes) and checked against it by `tests/u4_sites.rs`. Same row type and 64-byte guard rule as
//! the other tables; every function the helper calls and every instruction it relies on has a row.

use super::guard::{SeamKind, GUARD_BYTES};
use super::sites::{Feature, Site};

pub const UI_TEX_FIND_HANDLE_OFFSET: usize = 0x353da30;
pub const UI_TEX_MAKE_OFFSET: usize = 0x37852a0;
pub const UI_TEX_POLL_OFFSET: usize = 0x37a3510;
pub const UI_TEX_RELEASE_HANDLE_OFFSET: usize = 0x3540b10;
pub const UI_TEX_BIND_OFFSET: usize = 0x379e9c0;
pub const UI_TEX_CLEAR_OFFSET: usize = 0x379e470;
pub const UI_TEX_RELEASE_WEAK_OFFSET: usize = 0x39c2670;
#[cfg(test)]
pub const UI_TEX_READY_WORDS_OFFSET: usize = 0x379e610;
#[cfg(test)]
pub const UI_TEX_CTOR_OFFSET: usize = 0x37a31e0;
/// The lookup's `adrp`/`ldr` pair that names the file-resource service slot (inside the lookup row's window).
pub const UI_TEX_SERVICE_SLOT_WORDS_OFFSET: usize = 0x353da58;

pub static SITES: [Site; 9] = include!(concat!(env!("OUT_DIR"), "/tables/sites_u4.SITES.rs"));

const _: () = assert!(GUARD_BYTES == 64);
